  FT["PH-H5425"] = {"id":"PH-H5425","coverage":"full","language":"en","sourceName":"LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation）","sourceUrl":"https://lawphil.net/statutes/repacts/ra1990/ra_6935_1990.html","fetchedAt":"2026-10-06","articleCount":4,"structureMode":"ARTICLE","title":{"zh":"设立Dingalan市","en":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Dingalan, Province of Aurora, to be known as the Dingalan Municipal Hospital, and Appropriating Funds Therefor","orig":"An Act Establishing a Ten-Bed Municipal Hospital in the Municipality of Dingalan, Province of Aurora, to be known as the Dingalan Municipal Hospital, and Appropriating Funds Therefor","vi":"Đạo luật thành lập Bệnh viện Đô thị Dingalan tại Đô thị Dingalan, Tỉnh Aurora, và phân bổ kinh phí cho mục đích này","th":"พระราชบัญญัติจัดตั้งโรงพยาบาลเทศบาล Dingalan ในเทศบาล Dingalan จังหวัด Aurora และจัดสรรเงินทุนสำหรับการนี้","id":"Undang-Undang membentuk Rumah Sakit Kotamadya Dingalan di Kotamadya Dingalan, Provinsi Aurora, dan mengalokasikan dana untuk itu","ms":"Akta menubuhkan Hospital Perbandaran Dingalan di Perbandaran Dingalan, Wilayah Aurora, dan memperuntukkan dana untuk itu"},"level":"law","status":"active","topics":["health"],"docNumber":"Republic Act No. 6935","issuingBody":"Congress of the Philippines","promulgatedDate":"1990-03-09","completenessNote":"全文，共 4 条；逐字取自 LawPhil 菲律宾法律虚拟图书馆（The LawPhil Project – Arellano Law Foundation） 官方页面（statutes/repacts/ra1990/ra_6935_1990.html），未改写、未摘译、未节选；原文语言：英语。 条文抬头依源文为 “Section N.” 等形式，本库统一规范为 “Section N.”；首行抬头与条内标题的分段依源文块级边界还原。","country":"PH","countryName":"菲律宾","layer":"intl","articles":[{"id":"PH-H5425-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"There shall be established, under the supervision of the Department of Health, a ten-bed municipal hospital in the Municipality of Dingalan, Province of Aurora, to be known as the Dingalan Municipal Hospital."}},{"id":"PH-H5425-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"The amount necessary to carry out the provisions of this Act shall be charged against the appropriations authorized for the purpose under the Fiscal Year 1989 General Appropriations Act. Thereafter, such sums as may be necessary for the operation and maintenance of the herein hospital shall be included in the annual General Appropriations Act."}},{"id":"PH-H5425-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Before the construction of the hospital, the Secretary of Health shall issue a written assurance that personnel of the hospital will be appointed and that funds for its maintenance and operation have been appropriated."}},{"id":"PH-H5425-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"This Act shall take effect upon its approval."}}],"pack":"ph-p77"};
